+export function checkSchema(value, rules) {
+  const issues = [];
+
+  if (typeof rules !== 'object' || rules === null || Array.isArray(rules)) {
+    throw new RangeError('rules must be a plain object');
+  }
+
+  for (const field in rules) {
+    if (!Object.prototype.hasOwnProperty.call(rules, field)) {
+      continue;
+    }
+
+    const rule = rules[field];
+
+    if (typeof rule !== 'object' || rule === null || Array.isArray(rule)) {
+      throw new RangeError(`rule for field "${field}" must be a plain object`);
+    }
+
+    const unknownKeys = Object.keys(rule).filter(
+      k => !['required', 'type', 'minLength', 'pattern'].includes(k)
+    );
+    if (unknownKeys.length > 0) {
+      throw new RangeError(`Unknown rule keys for field "${field}": ${unknownKeys.join(', ')}`);
+    }
+
+    const { required, type, minLength, pattern } = rule;
+
+    if (required === true && (value === undefined || value === null)) {
+      issues.push({ field, code: 'MISSING' });
+      continue;
+    }
+
+    if (value !== null && typeof value !== 'object') {
+      throw new RangeError(`Expected object for field "${field}"`);
+    }
+
+    if (Array.isArray(value)) {
+      throw new RangeError(`Expected object for field "${field}", got array`);
+    }
+
+    if (typeof value === 'object' && value !== null) {
+      const proto = Object.getPrototypeOf(value);
+      if (proto !== null && proto !== Object.prototype) {
+        throw new RangeError(`Expected plain object for field "${field}"`);
+      }
+    }
+
+    if (type === 'string') {
+      if (typeof value !== 'string') {
+        issues.push({ field, code: 'TYPE' });
+      }
+    } else if (type === 'number') {
+      if (typeof value !== 'number') {
+        issues.push({ field, code: 'TYPE' });
+      }
+    } else if (type === 'boolean') {
+      if (typeof value !== 'boolean') {
+        issues.push({ field, code: 'TYPE' });
+      }
+    } else if (type === 'array') {
+      if (!Array.isArray(value)) {
+        issues.push({ field, code: 'TYPE' });
+      }
+    } else if (type === 'object') {
+      if (!(typeof value === 'object' && value !== null)) {
+        issues.push({ field, code: 'TYPE' });
+      } else {
+        const proto = Object.getPrototypeOf(value);
+        if (proto !== null && proto !== Object.prototype) {
+          issues.push({ field, code: 'TYPE' });
+        }
+      }
+    }
+
+    if (minLength !== undefined && minLength < 0) {
+      throw new RangeError(`minLength must be nonnegative for field "${field}"`);
+    }
+
+    if (minLength !== undefined && type === 'string' && value !== undefined && value !== null) {
+      if (value.length < minLength) {
+        issues.push({ field, code: 'MIN_LENGTH' });
+      }
+    }
+
+    if (pattern !== undefined && typeof pattern !== 'string') {
+      throw new RangeError(`pattern must be a string for field "${field}"`);
+    }
+
+    if (pattern !== undefined && type === 'string' && value !== undefined && value !== null) {
+      try {
+        new RegExp(pattern);
+      } catch (e) {
+        throw new RangeError(`Invalid regex pattern for field "${field}": ${e.message}`);
+      }
+    }
+  }
+
+  return Object.freeze(issues.map(issue => Object.freeze(issue)));
+}

